      "instructionsEn": "Write 3-4 English sentences about what you did yesterday or last weekend. Use **have** or **take** + noun to describe actions (for example **had a chat**, **took a photo**, **had/took a break**), and add at least one sentence with **have got** or **have** about something you own. Remember: don't use have got for the past, the future or after modal verbs.",
      "ruleSummary": "Have and have got can both express possession and relationships (She has / She's got a house in Italy); have is more formal. Only have (not have got) is used in to-infinitive and -ing forms, after modal verbs, in short answers (Yes, we have), and for the past and future (She had a racing bike; I will have time tomorrow; used to have). When have got is the perfect of get meaning obtain or receive, it can be used in those forms (pleased to have got a place; could have got more for it). Have + noun describes an action (have an argument, a chat, a meal, a say, a wash, a word). Some nouns take take but not have (take a message, care, a chance, a photo, power, responsibility, a risk, a dislike to). Some take either, with take more formal (have/take a walk, a bath, a break, a holiday, a look, a rest, a sip, a stroll, a swim). A correct student sentence must use the right verb for the noun and must not use have got where only have is possible."
