      "title": "Luyện với AI",
      "titleEn": "Practice with AI",
      "instructions": "Hãy viết 3-4 câu tiếng Anh về việc nhà và các hoạt động của bạn trong tuần, dùng **do** (ví dụ **do the shopping**, **do some gardening**, **do me a favour**) và **make** (ví dụ **make a decision**, **make a mistake**, **make a cake**). Thêm một câu dùng **would make** để nói một đồ vật cũ trong nhà bạn có thể dùng vào việc gì (ví dụ This old box would make a good ...).",
      "instructionsEn": "Write 3-4 English sentences about your chores and activities this week, using **do** (for example **do the shopping**, **do some gardening**, **do me a favour**) and **make** (for example **make a decision**, **make a mistake**, **make a cake**). Add one sentence with **would make** saying what an old object in your home could be used for (for example This old box would make a good ...).",
      "ruleSummary": "Do is used with certain nouns for activities or things that affect people (do homework, do damage, do somebody a favour, do (no) good, do housework, do research, do a job); informally it can replace verbs for certain jobs (do the shoes = clean them, do your hair); it is used for general or indefinite activities (Did you do anything about the window?). Do + the/some/a bit of + -ing noun is used for jobs and leisure (do the ironing, do some painting, do a bit of skiing), but not normally when the verb has an object (not do some book reading), except bird watching, letter-writing, note-taking and sightseeing. Make is used for constructing or creating (make clothes, make coffee) and with nouns for actions someone performs (make an announcement, an arrangement, a choice, a contribution, a decision, a discovery, an excuse, a mistake, a noise, an offer, a promise, a suggestion). Make also says how successful someone or something would be in a role or for a purpose (He would have made an excellent prime minister; That table would make a good TV stand). A correct student sentence must pair each noun with the verb English actually uses."
