              "text": "Other verbs like this include **give**, **lend**, **offer**, **promise**, **sell**, **teach**, **tell**, **throw**. However, verbs that can't be followed by object + object in the active have only one of these passive forms:",
              "vi": "Những động từ khác thuộc loại này gồm give, lend, offer, promise, sell, teach, tell, throw. Tuy nhiên, những động từ không thể theo sau bởi tân ngữ + tân ngữ ở câu chủ động thì chỉ có một trong hai dạng bị động này:"
