      "instructions": "Hãy viết 3-4 câu bị động tiếng Anh về một sự kiện gần đây ở trường, nơi làm việc hoặc khu phố của bạn. Dùng ít nhất một động từ có hai tân ngữ (ví dụ **I was given...**, **We were told...**) và một cụm động từ ở dạng bị động (ví dụ **was looked after**, **was talked into**). Nhớ rằng nội động từ như happen, arrive, exist không có dạng bị động.",
      "instructionsEn": "Write 3-4 English passive sentences about a recent event at your school, workplace or neighbourhood. Use at least one verb with two objects (for example **I was given...**, **We were told...**) and one multi-word verb in the passive (for example **was looked after**, **was talked into**). Remember that intransitive verbs such as happen, arrive and exist have no passive.",
      "ruleSummary": "Passive verb forms use a tense of be plus a past participle (The building was destroyed). Only transitive verbs (with an object) have passives; intransitive verbs such as sleep, disappear, arrive, happen, exist, recede and deteriorate do not (not The accident was happened). Verbs used both ways have a passive only in their transitive use (Is he being met at the airport? but When shall we meet? has no passive). Verbs taking object + object or object + prepositional object (give, hand, lend, offer, promise, sell, teach, tell, throw) have two passives (I was handed the plate / The plate was handed to me); verbs that cannot take object + object (describe, demonstrate, explain, introduce, mention, report, suggest) have only one (The situation was described to me, not I was described the situation). Transitive multi-word verbs can be passive (I was talked into buying a motorbike; He was operated on), but some are rarely passive: get back, put out a hand, get down, let in, let out, show off, take after. A correct student sentence must use be in the right tense plus a past participle, keep any preposition of a multi-word verb, and never make an intransitive verb passive."
