              "vi": "Trong tiếng Anh, chúng ta thường đặt thông tin cũ ở đầu câu (hoặc mệnh đề) và thông tin mới ở cuối. Chọn câu bị động thường giúp làm được điều này. Hãy so sánh hai đoạn văn sau và để ý vị trí của thông tin cũ (in nghiêng) và thông tin mới (in đậm) trong câu thứ hai của mỗi đoạn. Đoạn thứ hai dùng câu bị động:"
