      "ruleSummary": "Active and passive sentences present the same information in different orders: the active is about the agent (The storm damaged the roof), the passive about what happened to the object, with the agent optional in a by-phrase (The roof was damaged by the storm). Passives are preferred when the agent is unknown, is people in general, is unimportant or is obvious, so it can be omitted (My office was broken into; An order form can be found on page 2); in factual writing about procedures and processes (It can be stored as a liquid); and in formal English instead of subjects like people, somebody, they, we or you (The new system is being installed next month). A noun formed from a verb can be the subject with a new passive verb (The installation of the system will be completed by next month). Passives also help put old information first and new information last, and move a long agent to the end (I was surprised by Don's decision to give up his job). A correct student sentence must form the passive with be in the right tense plus a past participle, and choose the passive for one of these reasons rather than at random."
