      "instructionsEn": "Write 3-4 English sentences about your own experience using passive forms after verbs: one with **being + past participle** (e.g. **I hate being interrupted**), one with **to be + past participle** (e.g. **I hope to be promoted**), and one passive such as **I was taught to...** or **He was seen leaving...**.",
      "ruleSummary": "Passive forms after verb + -ing and verb + to-infinitive. Verb + -ing + object has a passive with being + past participle (I enjoyed taking the children to the zoo / The children enjoyed being taken to the zoo); verbs like this include avoid, consider, delay, deny, describe, imagine, remember, resent, and the active and passive do not have corresponding meanings. Verb + object + -ing has a passive with the object as subject (They saw him climbing over the fence / He was seen climbing over the fence), with bring, catch, hear, find, keep, notice, send, show. Some verbs with object + -ing have no passive: anticipate, appreciate, dislike, dread, forget, hate, imagine, like, (not) mind, recall, remember (I appreciated you coming, not You were appreciated coming). Verb + to-infinitive + object has a passive with to be + past participle (Tim started to be respected by his colleagues); with appear, begin, come, continue, seem, start, tend the meanings correspond, but with agree, aim, attempt, hope, refuse, struggle, try they do not (Kevin hoped to be selected). Verb + object + to-infinitive has a passive (Peter was taught to sing) with advise, allow, ask, believe, consider, expect, feel, instruct, mean, order, report, require, tell, understand; sometimes both verbs are passive (Changes are expected to be proposed). Some verbs with object + to-infinitive have no passive: (can't) bear, hate, like, love, need, prefer, want, wish (Susan liked Tom to be there, not Tom was liked to be there). Check each student sentence uses a passive only where the verb allows it and forms being/to be + past participle correctly."
