              "kind": "text",
              "text": "Notice that we can sometimes use *do* when *what*, *which*, *who* or *whose* is subject if we want to encourage the speaker to give an answer. *Do* is stressed in spoken English:",
              "vi": "Lưu ý rằng đôi khi chúng ta có thể dùng do khi what, which, who hoặc whose làm chủ ngữ, nếu muốn thúc người nghe trả lời. Trong văn nói, do được nhấn mạnh:"
