              "kind": "text",
              "text": "When we report a wh-question we use a reporting clause (see Unit 43) followed by a clause beginning with a wh-word. When we report a yes/no question we use a reporting clause followed by a clause beginning with either **if** or **whether**:",
              "vi": "Khi tường thuật câu hỏi wh-, chúng ta dùng mệnh đề tường thuật (xem Unit 43) theo sau là mệnh đề bắt đầu bằng từ để hỏi wh-. Khi tường thuật câu hỏi yes/no, chúng ta dùng mệnh đề tường thuật theo sau là mệnh đề bắt đầu bằng if hoặc whether:"
