      "instructionsEn": "Write 4-5 English sentences telling a story about something that happened to you (for example, getting lost or mistaking someone for somebody else). Use at least one transitive verb with its object, one intransitive verb, one verb used both ways (**The door closed** / **I closed the door**), and one verb that needs a completion such as **remind ... of**, **mistake ... for**, **belong to** or **object to**.",
      "ruleSummary": "Verbs with and without objects. Transitive verbs are followed by an object (Did you see your sister? He described the new building; also arrest, avoid, enjoy, find, force, give, grab, hit, pull, report, shock, tell, touch, want, warn). Intransitive verbs have no object (They arrived three hours late. He coughed; also appear, come, fall, go, happen, matter, sleep, swim, wait) and cannot be made passive. Some verbs are both, often for change (I closed the door / The door closed; break, burn, empty, increase, open, shut, spoil). Some transitive verbs can leave out the object when the context makes it clear (He has smoked since he was 10; answer, cook, drink, eat, read, sing, wash, win, write). Some verbs typically or always need a completion, an adverb or prepositional phrase: intransitive ones (The disease originated in Britain, not The disease originated; belong to, contend with, alternate between, aspire to, care for, culminate in, object to) and transitive ones (I always associate red wine with France; She put the report on the floor; base...on, compare...with, interest...in, lend...to, mistake...for, prevent...from, regard...as, remind...of, supply...with). Judge whether each student sentence gives every transitive verb its object where needed, avoids objects after intransitive verbs, and includes a required completion with the right preposition."
