      "instructionsEn": "Write 4-5 English sentences about things you have done or meant to do recently. Use at least two pairs of verbs whose meaning changes with a to-infinitive or -ing, for example **I remember going** / **Remember to take**, **I stopped to buy** / **I stopped eating**, **I tried to fix** / **I tried turning it off**, and one sentence with **advise** or **encourage** (with and without an object). You can also complete the open sentences of exercise 38.2 in your own way.",
      "ruleSummary": "Verb + to-infinitive or -ing. Some verbs take a to-infinitive but not -ing (agree, aim, ask, decline, demand, fail, hesitate, hope, hurry, manage, offer, plan, prepare, refuse, want, wish); others take -ing but not a to-infinitive (admit, avoid, consider, delay, deny, detest, dread, envisage, feel like, finish, imagine, miss, recall, resent, risk, suggest). Begin, cease, start and continue take either with little difference (they continued to play / playing), but two -ing forms together are avoided (I'm starting to learn, rather than starting learning). Advise and encourage take -ing with no object and a to-infinitive with an object (I'd advise taking / I'd advise you to take more exercise). With come, go on, mean, regret, remember, stop and try the meaning changes: came to accept (gradual change) vs came hurrying (way of moving); went on to sing (next action) vs went on tapping (continued); meant to phone (intended) vs means getting up (has as a result); regret to inform (about to say bad news) vs regret asking (sorry about a past action); remember to take (remembering first) vs remember going (action first); stopped to make tea (reason for stopping) vs stopped laughing (the activity stopped); tried to get the table through (attempt) vs tried taking aspirin (experiment to see if it helps). Judge whether each student sentence chooses the form that matches the verb and the intended meaning."
