      "instructionsEn": "Write 3-4 English sentences about something you once witnessed or remember: one with a verb that needs an object (**I saw two people arguing** ...), one with a verb that takes no object (**I enjoy walking** ...), one with **having** + past participle (**I regret having** ...), and one contrasting an -ing form with a bare infinitive after **watch**/**hear**.",
      "ruleSummary": "Verb + -ing patterns. Some verbs must have an object before the -ing form (catch, discover, feel, find, hear, leave, notice, observe, overhear, see, spot, watch: The police found the man climbing the wall), except in the passive (The man was found climbing the wall). Some can have an object or none (can't stand, detest, dislike, dread, envisage, hate, imagine, like, love, mind, miss, recall, regret, remember, resent, risk, start, stop: I remember (you) buying that jumper). Some can't have an object (admit, advise, consider, continue, delay, deny, deserve, enjoy, escape, face, finish, forget, propose, put off, suggest: He continued playing). Admit, deny, forget, recall, regret and remember can take having + past participle with little difference in meaning (I now regret having bought the car). With verbs of (dis)liking and thinking, a person object can be possessive, which is rather formal (I resented Tom's winning the prize), but not a non-person (the horse winning, not the horse's winning). After feel, hear, notice, observe, overhear, see, watch, an -ing form suggests a repeated action, one over a period, or seeing only part of it (I heard the dogs barking most of the night), while a bare infinitive suggests a single action seen from start to finish (I watched him climb through the window). Judge whether each student sentence uses the right pattern and object."
