              "kind": "text",
              "text": "We can use **hear**, **feel**, **see** and **watch** followed by an object + past participle to talk about hearing, etc. something happen. After **feel**, the object is often a reflexive pronoun:",
              "vi": "Chúng ta có thể dùng hear, feel, see và watch + tân ngữ + quá khứ phân từ để nói về việc nghe, thấy ... một điều gì đó xảy ra. Sau feel, tân ngữ thường là đại từ phản thân:"
