      "instructions": "Đây là một số động từ thường dùng trong cấu trúc get/have something done. Bạn có biết chúng nghĩa là gì không? Chạm một cụm bên trái, sau đó chạm nghĩa phù hợp bên phải. (A)",
      "instructionsEn": "Here are some verbs commonly used in the pattern get/have something done. Do you know what they mean? Tap a phrase on the left, then tap the meaning on the right that goes with it. (A)",
