      "instructions": "Hãy viết 3-4 câu tiếng Anh về những việc bạn thường nhờ người khác làm hoặc muốn được làm: một câu với **have/get something done** (**I had my hair cut** ...), một câu với **get** khi chính bạn gây ra chuyện (**I got my finger caught** ...), một câu với **won't have** và một câu với **want/need/would like** + tân ngữ + quá khứ phân từ.",
      "instructionsEn": "Write 3-4 English sentences about things you usually have done for you or want done: one with **have/get something done** (**I had my hair cut** ...), one with **get** where you caused what happened (**I got my finger caught** ...), one with **won't have**, and one with **want/need/would like** + object + past participle.",
      "ruleSummary": "Have/get + object + past participle means arranging for someone else to do something (We had/got the car delivered to the airport); got is informal, and word order matters (had the car delivered vs had delivered the car, past perfect). Have is used when the subject has no control or responsibility (I had my appendix removed; They had their car broken into), and when focusing on the result (I'll have the house cleaned by the time you get home). Get is used when the subject does it themselves, causes it or is to blame (I'll get the house cleaned; Sue got her fingers trapped). Won't have (not get) means not allowing something (I won't have him spoken to like that). Need, prefer, want, would like + object + past participle, optionally with to be, say something should be done (I'd like my car (to be) serviced); after need, object + -ing is also possible (the house redecorating), but not to be + -ing. Hear, feel, see, watch + object + past participle describe perceiving something happen with passive meaning (I heard her called Toni; I felt myself thrown forward), contrasting with the active bare infinitive (I heard Sue call Toni). Judge whether each student sentence uses the right verb, word order and participle."
