      "instructionsEn": "Write 3-4 English sentences about gifts or help you have given or received: one with two objects (**She gave me a book** ...), one reversed with **to** or **for** (**I bought a present for my mother** ...), one with a verb that only takes **to**, such as explain or describe, and one with a verb that can't be reversed, such as cost or envy.",
      "ruleSummary": "Verbs with two objects: usually object 1 is a person and object 2 a thing (Can you bring me some milk?). With many verbs the order can be reversed by putting for or to before the person (They built a new house for us; Can you give that bandage to me?), especially to focus on that person or when object 1 is much longer (Jasmin taught music to a large number of children at the school). For is used with book, build, buy, catch, choose, cook, fetch, find, make, order, pour, save; to with award, give, hand, lend, offer, owe, pass, show, teach, tell, throw; either with bring, leave, pay, play, post, read, send, sing, take, write, sometimes with a difference (took apples to my sister = she received them; took the books for her = on her behalf). Allow, ask, cost, deny, envy, forgive, guarantee, permit, refuse take two objects but can't be reversed (We envied him his lifestyle; Her coat cost her a fortune). Admit, announce, confess, demonstrate, describe, explain, introduce, mention, point out, prove, report, say, suggest only take a second object with to (explained the procedure to me, not explained me the procedure), and collect, mend, raise only with for (raised money for charity). Judge whether each student sentence orders the objects correctly and uses the right preposition."
