      "instructionsEn": "Write 3-4 English sentences reporting a recent conversation of yours: one direct quotation with the reporting clause after it ('...,' **she said**), one report in your own words with a that-clause, one negative with **didn't think** or **didn't expect**, and one sentence with a reporting noun such as **the decision to** or **the question of**.",
      "ruleSummary": "Reporting people's words and thoughts. Actual words can be quoted, with the reporting clause before, within or after the quotation ('I suppose you've heard the latest news,' she said). In stories the reporting verb often comes before a noun subject after the quotation ('When will you be back?' asked Arnold), but not before a pronoun (she continued, not continued she). More commonly we report in our own words with a reporting clause plus a reported clause (She explained that she couldn't take the job until January). To report what someone didn't say, the reporting verb is negative (He didn't tell me how...); a negative statement is normally reported in the reported clause (He agreed that it wasn't a good idea), but with think, believe, expect, feel, intend, plan, propose, suppose, want the reporting verb is made negative instead (She didn't think it was dangerous, rather than She thought it wasn't). Reporting nouns can be followed by a that-clause (claim, decision, guarantee, observation, warning...; that is not usually left out), a to-infinitive (invitation, encouragement, threat, promise, order...), or of + wh-clause (issue, problem, question). Judge whether each student sentence reports correctly with natural word order, negative placement and noun + clause pattern."
