              "kind": "text",
              "text": "If we use a *that*-clause after the verb *notify*, then we must use an object ('the bank') between the verb and the *that*-clause, and this object can't be a prepositional object (see E below). So we can't say 'I notified that I ...' or 'I notified to the bank that I ...'.",
              "vi": "Nếu dùng mệnh đề that sau động từ notify, ta bắt buộc phải có một tân ngữ ('the bank') giữa động từ và mệnh đề that, và tân ngữ này không được là tân ngữ có giới từ (xem E bên dưới). Vì vậy không thể nói 'I notified that I ...' hay 'I notified to the bank that I ...'."
