              "vi": "Khi tình huống được mô tả trong mệnh đề that là lâu dài, hoặc vẫn còn tồn tại hay còn liên quan vào lúc ta tường thuật, thì ta dùng thì hiện tại (hoặc hiện tại hoàn thành) nếu động từ trong mệnh đề tường thuật cũng ở thì hiện tại:"
