      "instructions": "Hãy viết 3-4 câu tiếng Anh thuật lại tin tức hoặc lời người khác đã nói với bạn. Viết ít nhất một câu mà tình huống vẫn còn đúng (**She told me that she lives ...**), một câu mà sự việc đã qua (**He said that he was ...**), và một câu thuật lại một sự việc vốn đã ở quá khứ trong câu nói gốc (**She mentioned that she had ...**).",
      "instructionsEn": "Write 3-4 English sentences reporting news or what someone has told you. Include at least one where the situation is still true (**She told me that she lives ...**), one where it is now past (**He said that he was ...**), and one reporting something that was already past in the original statement (**She mentioned that she had ...**).",
      "ruleSummary": "Verb tense in reported that-clauses. The tense chosen is the one appropriate at the time of reporting, so it may differ from the original ('Tim is much better.' She said that Tim was much better). If the situation is permanent, still exists or is still relevant and the reporting verb is present, the that-clause uses a present tense or present perfect (Dr Weir thinks that he spends about 5 minutes..., not spent; Jill says that Colin has been found, not had been found). With a past reporting verb, either present or past is possible (She argued that Carl is/was the best person); the present emphasises that the situation still exists. A past tense suggests the speaker is not sure it is true or that it may no longer be the case (Sarah told me that she had two houses). If the situation is past at the time of reporting, a past tense is used (Bob announced that he was leaving). If it was already past in the original statement, the past perfect is usual, though the past simple is often possible ('I posted the card yesterday.' She reassured me that she had posted/posted the card). Judge whether each student sentence chooses a tense in the that-clause that fits the time of reporting and the meaning."
