      "instructionsEn": "Write 3-4 English sentences reporting what friends or colleagues told you last week. Use **said** and **told** correctly (**told me that**, **said to me that**, **told me about**), change pronouns and time words as needed (**that day**, **the next day**), and write one sentence with **admitted**, **denied** or **mentioned** + -ing.",
      "ruleSummary": "Reporting statements: tense of the reporting verb, other changes, say and tell, and -ing clauses. When reporting past speech the reporting verb is often past (She revealed that she had been married before), but for current news and opinions a present tense is possible (The teacher says/said that...), and it is preferred for information heard but not known to be true (Ben tells me you're moving back to Greece; I hear you're unhappy) and for general statements or what an authority says (Everyone says...; The law says that...). Reporting in a different context often requires changing pronouns, time and place references and this/that/these as well as tense ('Jim's arriving later today.' She said that Jim was arriving later that day; here becomes there; these becomes those). Tell needs an object (He told me that..., not told that...); say has no direct object (not said me that) but can take to + object (I said to John that...; not told to John); tell + object + about reports a topic (She told me about her holiday, not said about). Admit, deny, mention and report can take an -ing clause (He denied hearing the warnings = He denied that he (had) heard...). Judge whether each student sentence uses said/told correctly, adjusts pronouns, time words and tense, and forms any -ing report correctly."
