      "instructionsEn": "Write 3-4 English sentences reporting what people have said to you recently: an invitation or reminder (**invited me to**, **reminded me to**), a promise or offer of help (**promised to**, **offered to**), and a piece of advice using **suggested / recommended / advised** + -ing (for example advice from a teacher or doctor). You can add one sentence with **suggested that** + clause.",
      "ruleSummary": "Reporting offers, suggestions, orders, intentions, promises and requests. Some reporting verbs take object + to-infinitive, where the object is the person the offer or order is made to (She encouraged Frank to take the job; also advise, ask, command, compel, expect, instruct, invite, order, persuade, recommend, remind, request, tell, urge, warn). Others take a to-infinitive with no object (She offered to take me to town, not She offered me to take; also agree, demand, guarantee, hope, promise, swear, threaten, volunteer, vow); ask without an object asks permission (I asked to see his identification). Some verbs take either a that-clause or a to-infinitive (He claimed to be innocent / He claimed that he was innocent; agree, demand, expect, guarantee, hope, promise, propose, request, vow). Advise, insist, order, say and suggest take a that-clause but not a to-infinitive (He suggested that we went home early, not suggested to go), though informal say can take a to-infinitive (Tim said to put the box on the table) and advise/order can take object + to-infinitive. Intend, want, long, offer, plan, refuse, volunteer take a to-infinitive but not a that-clause. Advise, propose, recommend and suggest can be followed by an -ing clause to report a suggested action (The lecturer recommended reading a number of books). Judge whether each student sentence uses a reporting verb with a pattern it allows and is well formed."
