      "instructionsEn": "Write 3-4 English sentences giving advice to people in a difficult situation (for example someone about to climb Mt Everest, someone trying to give up smoking, someone who wants to learn the bagpipes), starting with **It is** + adjective (**vital**, **essential**, **important**, **necessary**) + a that-clause with **should**. Add one sentence reporting a formal recommendation with the subjunctive (for example **We recommend that the building be ...**).",
      "ruleSummary": "Should in that-clauses. Advice, orders, requests and suggestions about things that need to be done can be reported with a that-clause containing should + bare infinitive (They have proposed that Jim should move to their London office), often should be + past participle or adjective (The report recommends that the land should not be sold). In formal, especially written, English should can be left out, keeping the bare infinitive, the subjunctive (They directed that the building be pulled down; It was agreed that the company not raise its prices); in less formal English an ordinary tense is used (They recommended that he gives up writing). Verbs such as advise, ask, beg, command, demand, instruct, intend, order, request, require, stipulate, warn, and related nouns (an order that, a warning that), take this pattern. Should is also used after be + adjective of reaction (amazed, anxious, concerned, disappointed, surprised, upset): I am concerned that she should think I stole the money; without should an ordinary tense is used (that she thinks), never a bare infinitive (not that she think). After it + be + adjective such as crucial, essential, imperative, important, (in)appropriate, (un)necessary, vital, should or sometimes the subjunctive is used (It is important that she (should) understand). Judge whether each student sentence uses should, the subjunctive or an ordinary tense correctly for its pattern and level of formality."
