              "kind": "text",
              "text": "However, when *shall* is used in offers, requests for advice and confirmation, etc. then we can use **should** in the report, but not *shall* (see also Unit 25C):",
              "vi": "Tuy nhiên, khi shall được dùng trong lời đề nghị, lời xin lời khuyên hay xin xác nhận, v.v., ta có thể dùng should trong câu tường thuật, nhưng không dùng shall (xem thêm Unit 25C):"
