      "instructions": "Hãy viết 3-4 câu tiếng Anh tường thuật lại những gì một người bạn hoặc đồng nghiệp đã nói với bạn tuần này, trong đó câu gốc có động từ khuyết thiếu: một lời khuyên (**should / ought to**), một việc bắt buộc (**must / had to**), một lời cấm (**mustn't**) và một dự định hoặc khả năng (**would / will**, **might / may**). Hãy nghĩ xem động từ khuyết thiếu có cần đổi hay không.",
      "instructionsEn": "Write 3-4 English sentences reporting what a friend or colleague said to you this week, where the original words contained a modal verb: some advice (**should / ought to**), an obligation (**must / had to**), a prohibition (**mustn't**) and a plan or possibility (**would / will**, **might / may**). Think about whether the modal needs to change.",
      "ruleSummary": "Modal verbs in reported speech. Could, would, should, might, ought to and used to do not change in the report (He said that he could meet us at the airport). Will, can and may usually become would, could and might (I warned him he would fall through the ice), but if the situation still exists or is still future and the reporting verb is present, will, can and may are preferred (She tells me she'll be in Paris at Christmas); with a past reporting verb either form is possible (They said the problem can/could be solved). Shall about the future becomes would (She told me she would call me on Monday); shall in offers and requests for advice becomes should, never shall (He asked where he should put the box). Must for necessity becomes must or had to (She said I must / had to be home by 9); must for a conclusion stays must, not had to (Neil said he must be getting old); mustn't stays mustn't, not didn't have to. A modal can appear in a report even without one in the original ('You're not allowed to smoke here' becomes She told me that I mustn't smoke there). Judge whether each student sentence reports the modal meaning correctly with an appropriate modal and backshift, and is well formed."
