      "ruleSummary": "Countable and uncountable nouns. Countable nouns can take a/an and be plural (three children, a dog); uncountable nouns cannot (fresh air, not an air or airs). Many nouns are normally uncountable in English even if countable in other languages: accommodation, advice, baggage, cash, equipment, evidence, furniture, homework, housework, information, jewellery, luggage, machinery, news, progress, research, rubbish, scenery, sunshine, transport, weather, work (not an advice, informations, furnitures, a work meaning a job). Some nouns are uncountable for the whole substance or idea but countable for a container (Three teas, please), a type or brand (dozens of cheeses), a particular physical example (a hair in my soup) or a particular instance (a stone in my shoe; a winter sport): e.g. beer, coffee, cake, chicken, noise, stone, difficulty, dislike, improvement, language, life, success, war. Some change meaning: tin (metal) / tins (containers); also competition, glass, iron, paper, property, room, speech, time, work. Education, importance, knowledge, resistance, traffic can be countable only in the singular (an extensive knowledge of property prices); damage is countable only in the plural, meaning compensation (claiming damages). Judge whether each student sentence uses a/an, plural forms and verb agreement correctly for countable and uncountable nouns."
